const BAR_COUNT = 60;

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const masterProgress = spring({
    frame,
    fps,
    delay: 0,
    config: { damping: 200 },
  });

  const counterProgress = spring({
    frame,
    fps,
    delay: 8,
    config: { damping: 200 },
  });
  const counter = Math.round(interpolate(counterProgress, [0, 1], [0, 500]));

  const labelProgress = spring({
    frame,
    fps,
    delay: 30,
    config: { damping: 200 },
  });

  const subProgress = spring({
    frame,
    fps,
    delay: 50,
    config: { damping: 200 },
  });

  const drift = frame * 0.4;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif", backgroundColor: COLORS.bg }}>

      {/* ── Animated bar forest behind everything ── */}
      <AbsoluteFill style={{ overflow: "hidden" }}>
        {Array.from({ length: BAR_COUNT }).map((_, i) => {
          const seed = (i * 137.508) % 1;
          const x = (i / BAR_COUNT) * 3840;
          const baseH = 80 + seed * 420;
          const phase = (i * 53.7) % 360;
          const animH =
            baseH + Math.sin(((drift + phase) * Math.PI) / 180) * baseH * 0.35;
          const barW = 28 + seed * 24;
          const opacity = 0.03 + seed * 0.07;
          const redTint = i % 7 === 0;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                bottom: 0,
                left: x,
                width: barW,
                height: animH * masterProgress,
                borderRadius: "6px 6px 0 0",
                background: redTint
                  ? `rgba(255,0,0,${opacity * 1.8})`
                  : `rgba(255,255,255,${opacity})`,
              }}
            />
          );
        })}
      </AbsoluteFill>

      {/* ── Radial glow behind the number ── */}
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: masterProgress,
        }}
      >
        <div
          style={{
            position: "absolute",
            width: 1100,
            height: 1100,
            borderRadius: "50%",
            background:
              "radial-gradient(circle, rgba(255,0,0,0.18) 0%, transparent 70%)",
          }}
        />
      </AbsoluteFill>

      {/* ── Orbiting tick marks ── */}
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: interpolate(masterProgress, [0, 1], [0, 0.5]),
        }}
      >
        <svg
          width="900"
          height="900"
          viewBox="0 0 900 900"
          style={{
            transform: `rotate(${frame * 0.12}deg)`,
          }}
        >
          {Array.from({ length: 60 }).map((_, i) => {
            const angle = (i / 60) * 2 * Math.PI;
            const isLong = i % 5 === 0;
            const r1 = isLong ? 410 : 418;
            const r2 = 428;
            const x1 = 450 + Math.cos(angle) * r1;
            const y1 = 450 + Math.sin(angle) * r1;
            const x2 = 450 + Math.cos(angle) * r2;
            const y2 = 450 + Math.sin(angle) * r2;
            return (
              <line
                key={i}
                x1={x1}
                y1={y1}
                x2={x2}
                y2={y2}
                stroke={isLong ? COLORS.red : "rgba(255,255,255,0.5)"}
                strokeWidth={isLong ? 3 : 1.5}
              />
            );
          })}
          <circle
            cx="450"
            cy="450"
            r="400"
            fill="none"
            stroke="rgba(255,255,255,0.06)"
            strokeWidth="1"
          />
        </svg>
      </AbsoluteFill>

      {/* ── Main number + text ── */}
