              color: COLORS.muted,
              letterSpacing: "0.04em",
            }}
          >
            of video uploaded to YouTube
          </span>
          <div
            style={{
              backgroundColor: "rgba(255,0,0,0.12)",
              border: "1.5px solid rgba(255,0,0,0.4)",
              borderRadius: 12,
              padding: "10px 28px",
              fontSize: 40,
              fontWeight: 800,
              color: COLORS.red,
              letterSpacing: "0.06em",
            }}
          >
            EVERY MINUTE
          </div>
        </div>
      </AbsoluteFill>

      {/* ── Floating mini video thumbnails ── */}
      {[
        { x: 320, y: 380, delay: 18, size: 180, rot: -8 },
        { x: 3200, y: 320, delay: 24, size: 160, rot: 6 },
        { x: 420, y: 1500, delay: 32, size: 140, rot: 4 },
        { x: 3300, y: 1560, delay: 28, size: 170, rot: -5 },
        { x: 700, y: 900, delay: 40, size: 120, rot: 9 },
        { x: 3000, y: 950, delay: 36, size: 130, rot: -7 },
      ].map((t, i) => {
        const prog = spring({
          frame,
          fps,
